function hundredDollar(ballots) {
  var totals = {}, invalid = [], gamed = [];
  ballots.forEach(function (b) {
    var vals = Object.keys(b.alloc || {}).map(function (k) { return b.alloc[k]; });
    var bad = vals.some(function (v) { return typeof v !== 'number' || v < 0 || Math.floor(v) !== v; });
    var sum = vals.reduce(function (s, v) { return s + (typeof v === 'number' ? v : 0); }, 0);
    if (bad || sum !== 100) { invalid.push(b.voter); return; }
    Object.keys(b.alloc).forEach(function (k) { totals[k] = (totals[k] || 0) + b.alloc[k]; });
    if (vals.some(function (v) { return v > 60; })) gamed.push(b.voter);
  });
  var ranking = Object.keys(totals).sort(function (a, b) { return totals[b] - totals[a] || (a < b ? -1 : a > b ? 1 : 0); });
  return { totals: totals, ranking: ranking, invalid: invalid, gamed: gamed };
}
